-- Autostart
hl.on("hyprland.start", function()
	hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("dbus-update-activation-environment --systemd --all")
	hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("systemctl --user start hyprpolkitagent")
	hl.exec_cmd("~/.config/hypr/scripts/resetxdgportal.sh")
	hl.exec_cmd("~/.config/ags/themes/init.sh")
	hl.exec_cmd("~/.config/hypr/scripts/wallpaperdaemon.sh")
	hl.exec_cmd("~/.config/hypr/scripts/controls.sh")
	hl.exec_cmd("~/.config/hypr/scripts/monitor_script.sh")
	hl.exec_cmd("/usr/bin/dunst")
	hl.exec_cmd("/usr/bin/fcitx5")
	hl.exec_cmd("/usr/bin/waybar -c ~/.config/waybar/config-river -s ~/.config/waybar/river_style.css")
	hl.exec_cmd("udiskie --tray --automount")
end)
